 */
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { openActionLog, type ActionLog } from "./action-log";
import type { BatchFile, BatchItem } from "./batch";
import { nextBumpAt, parseCooldownText } from "./cooldown";
import {
	cardBump,
	confirmBump,
	editPriceField,
	editPriceReady,
	forbiddenLabel,
	keyboardOpen,
	onBumpSheet,
	parseNodes,
	parseWon,
	priceField,
	type ScreenNode,
	type ScreenOp,
} from "./bump-screen";
import { droidOf } from "./droid";
import { parseSalesDump } from "./dump";
import { dumpScreen, settledDump } from "./node-dump";
import { adbExec, findPhoneSerial, PHONE_MISSING, type AdbExec } from "./phone";
import { alreadyAppliedToday, guardSnapshot } from "./rules";

const CONFIRM_BUMP = "끌어올리기";
const CONFIRM_EDIT = "수정 완료";
export const STOPPED_NOTE = "중단해서 멈췄어요";
/** 나의 당근에 판매관리 행이 없다. 앱이 등록한 내 판매 딥링크만 연다. */
export const KARROT_SALES = "karrot://my_sales";

let journal: ActionLog | null = null;
let journalSerial = "";
/** 마지막 덤프. 화면을 움직이는 명령(input·am)이 없으면 잠깐 동안 다시 쓴다. 덤프 한 번이 2초쯤 걸린다. */
let screen: { serial: string; xml: string; at: number } | null = null;
const SCREEN_REUSE_MS = 3000;

/** 화면을 바꾸는 adb 명령이 지나가면 마지막 덤프를 버린다. */
function watchMoves(exec: AdbExec): AdbExec {
	const wrapped: AdbExec = (args) => {
		const shell = args.indexOf("shell");
		const cmd = shell >= 0 ? (args[shell + 1] ?? "") : "";
		if (/^(input|am)\b/.test(cmd)) screen = null;
		return exec(args);
	};
	// `.droid` 를 들고 가야 dumpScreen 이 uiautomator 대신 `droid dump` 를 쓴다.
	const d = droidOf(exec);
	return d ? Object.assign(wrapped, { droid: d }) : wrapped;
}
let stop = false;
let stopFile: string | null = null;

/** 중단 요청(SIGTERM). 다음 단계 경계에서 멈춘다. 확정 버튼은 누르지 않는다. */
export function requestStop() {
	stop = true;
}

/**
 * 회차가 동기 코드로만 돌아 SIGTERM 핸들러가 이벤트 루프를 못 타므로, 중단 표시 파일을 단계마다 직접 본다.
 * 파일이 생기면 중단으로 친다.
 */
export function watchStopFile(path: string | null) {
	stopFile = path;
}

export function resetStop() {
	stop = false;
}

export function stopRequested(): boolean {
	if (stop) return true;
	if (stopFile !== null && existsSync(stopFile)) stop = true;
	return stop;
}

/** 끌어올리기 횟수·쿨타임을 저장소에 남기는 최소 인터페이스. bump-phone 은 저장소를 모른다. */
export type BumpBook = {
	previousBumpCount(listingId: string): number;
	recordBump(listingId: string, data: { bumpedAt: string; bumpCount: number; nextBumpAt: string | null }): void;
	recordCooldown(listingId: string, nextBumpAt: string): void;
	/** 당근에서 예약중으로 바뀐 글. 사이트가 바로 예약중으로 보이게 한다. */
	recordReserved?(listingId: string): void;
};

export type RunOptions = {
	log?: ActionLog;
	book?: BumpBook;
	/** 폰 시리얼 찾기. 기본은 droid `serial`. 테스트는 가짜를 넣는다. */
	findSerial?: () => string | null;
};

export type PhoneRun = {
	bumped: number;
	pricedOnly: number;
	skipped: number;
	note: string;
	touched: boolean;
	confirmed: boolean;
	ops: ScreenOp[];
	stopped: boolean;
	/** 실패할 때만. 사이트 메모에는 넣지 않는다. */
	logDir?: string;
};

export function keyguardLocked(blob: string): boolean | null {
	if (blob.includes("isKeyguardShowing=true")) return true;
	if (blob.includes("isKeyguardShowing=false")) return false;
	return null;
}

export function runDryWindow(base: AdbExec = adbExec, options: RunOptions = {}): PhoneRun {
	const exec = watchMoves(base);
	screen = null;
	const serial = (options.findSerial ?? findPhoneSerial)();
	if (!serial) return fail(PHONE_MISSING, false);
	const ops: ScreenOp[] = [];
	journal = options.log ?? openActionLog();
	journalSerial = serial;
	stop = false;
	wake(serial, exec);
	const locked = readLocked(serial, exec);
	if (locked) return fail("폰이 잠겨 있어요. PIN은 넣지 않아요", false);
	openSales(serial, exec);
	const opened = openReadySheet(serial, exec, ops);
	if (!opened) return fail("끌어올리기 창을 열 수 있는 글이 없어요", true, ops);
	const plan = readSheet(opened.xml, opened.title);
	backToSales(serial, exec, ops);
	if (!plan.ok) return fail(plan.message, true, ops);
	if (!noConfirm(ops)) return fail("확정 버튼을 누르지 말아야 하는데 눌렀어요", true, ops);
	return {
		bumped: 0,
		pricedOnly: 0,
		skipped: 0,
		note: `드라이런: ${opened.title} 가격 칸 ${plan.price.toLocaleString("ko-KR")}원. 확정은 누르지 않았어요`,
		touched: true,
		confirmed: false,
		ops,
		stopped: false,
	};
}

export function runApprovedOnPhone(
	batch: BatchFile,
	base: AdbExec = adbExec,
	listPrices?: ReadonlyMap<string, number>,
	options: RunOptions = {},
): PhoneRun {
	const exec = watchMoves(base);
	screen = null;
	const serial = (options.findSerial ?? findPhoneSerial)();
	if (!serial) return fail(PHONE_MISSING, false);
	const ops: ScreenOp[] = [];
	journal = options.log ?? openActionLog();
	journalSerial = serial;
	stop = false;
	wake(serial, exec);
	if (readLocked(serial, exec)) return fail("폰이 잠겨 있어요. PIN은 넣지 않아요", false);
	openSales(serial, exec);
	const tally = walkApproved(serial, exec, ops, batch, listPrices, options.book);
	const bumped = tally.bumped;
	const pricedOnly = tally.pricedOnly;
	const skipped = tally.skipped;
	const already = tally.already;
	if (tally.stop) return stopped(bumped, pricedOnly, skipped, ops, stopRequested());
	const applied = already > 0 ? `이미 오늘 가격인 ${already}건은 건너뛰었어요` : "";
	const summary = `끌어올리기 ${bumped} · 가격만 ${pricedOnly} · 건너뜀 ${skipped}`;
	return {
		bumped,
		pricedOnly,
		skipped,
		note: applied === "" ? summary : `${summary}. ${applied}`,
		touched: ops.length > 0,
		confirmed: ops.some((op) => op.kind === "tap" && (op.label === CONFIRM_BUMP || op.label === CONFIRM_EDIT)),
		ops,
		stopped: false,
	};

