export type PhoneRead =
	{ ok: true; cards: DumpCard[]; dumps: number; serial: string } | { ok: false; message: string; titles?: string[] };

/** 판매중 탭 개수와 모은 카드 수가 같을 때만 저장소를 갈아끼운다. */
export function salesReadComplete(count: number, tabCount: number | null): boolean {
	return tabCount !== null && count === tabCount;
}

/** trace: 창마다 개수만 받는다(제목·가격은 넘기지 않는다). 빠진 카드를 찾을 때 쓴다. */
export function readSalesFromPhone(trace?: (line: string) => void): PhoneRead {
	const serial = findPhoneSerial();
	if (!serial) return { ok: false, message: `${PHONE_MISSING}. 포트를 추측하지 않아요.` };

	let xml = dumpXml(serial);
	let parsed = parseSalesDump(xml);
	// 글 상세에도 `판매중` 글자가 있어 판매 목록이 아닌 화면이 no-sales 로 나올 수 있다.
	if (!parsed.ok && parsed.error.kind !== "ambiguous-stats") {
		openKarrot(serial);
		// 앱이 다른 화면이나 콜드 스타트면 판매관리가 늦게 그려진다. 한 번만 보지 않고 몇 번 다시 본다.
		for (let attempt = 0; attempt < 4; attempt++) {
			sleep(rand(1400, 2600));
			xml = dumpXml(serial);
			parsed = parseSalesDump(xml);
			if (parsed.ok || parsed.error.kind === "ambiguous-stats") break;
		}
	}
	if (!parsed.ok) {
		const where = parsed.error.kind === "not-sales-screen" ? ` (지금 화면: ${focusOf(serial, adbExec)})` : "";
		return { ok: false, message: `${parsed.error.message}${where}` };
	}

	// 트리는 보이는 2~3장만 남긴다. 꼭대기에서 아래로 당기면 새로고침만 반복된다.
	// 맨 아래로 내린 뒤, 아래에서 위로 밀며 겹쳐 모은다.
	tapSellingTab(serial, xml);
	scrollUntilStable(serial, swipeTowardBottom);
	xml = settledXml(serial);
	parsed = parseSalesDump(xml);
	if (!parsed.ok) return { ok: false, message: parsed.error.message };
	captureThumbs(serial, parsed.cards);

	let ordered = parsed.cards;
	let tabCount = parsed.tabCount;
	trace?.(`bottom: cards ${ordered.length} tab ${tabCount}`);
	const target = tabCount ?? ordered.length;
	let dumps = 1;
	let windowKey = visibleKey(parsed.cards);
	let stuck = 0;
	while (ordered.length < target && dumps < 90) {
		swipeTowardTop(serial);
		xml = settledXml(serial);
		parsed = parseSalesDump(xml);
		if (!parsed.ok) return { ok: false, message: parsed.error.message };
		captureThumbs(serial, parsed.cards);
		if (parsed.tabCount !== null) tabCount = parsed.tabCount;
		// 앞 창과 겹치는 카드가 없으면 그 사이 카드를 건너뛴 것이다. 반쯤 되돌아가 다시 읽는다.
		const known = new Set(ordered.map((card) => card.title));
		if (parsed.cards.length > 0 && !parsed.cards.some((card) => known.has(card.title))) {
			swipeAxis(serial, BACK_HALF);
			const back = parseSalesDump(settledXml(serial));
			if (back.ok) ordered = mergeSalesOrder(ordered, back.cards);
			dumps += 1;
		}
		const before = ordered.length;
		ordered = mergeSalesOrder(ordered, parsed.cards);
		dumps += 1;
		trace?.(
			`window ${dumps}: status ${(xml.match(/text="(판매중|예약중)" content-desc=""/g) ?? []).length} cards ${parsed.cards.length} overlap ${parsed.cards.filter((card) => known.has(card.title)).length} new ${ordered.length - before} total ${ordered.length}/${tabCount}`,
		);
		const nextKey = visibleKey(parsed.cards);
		if (nextKey !== "" && nextKey === windowKey) {
			stuck += 1;
			if (stuck >= 2) break;
		} else {
			stuck = 0;
		}
		windowKey = nextKey;
	}
	if (!salesReadComplete(ordered.length, tabCount)) {
		const found = tabCount === null ? "탭 개수를 못 읽음" : `판매중 ${tabCount}건`;
		return {
			ok: false,
			message: `${found} 중 ${ordered.length}건만 읽었어요. 저장소를 갈아끼우지 않아요.`,
			titles: ordered.map((card) => card.title),
		};
	}
	return { ok: true, cards: ordered, dumps, serial };
}

function adb(serial: string, args: string[]): string {
	const result = adbExec(["-s", serial, ...args]);
	return `${result.stdout}${result.stderr}`;
}

function dumpXml(serial: string): string {
	return dumpScreen(serial, adbExec);
}

function settledXml(serial: string): string {
	return settledDump(() => dumpXml(serial));
}

function openKarrot(serial: string) {
	adb(serial, ["shell", "am", "start", "-a", "android.intent.action.VIEW", "-d", KARROT_SALES]);
}

