export const TOWARD_BOTTOM = { y1: 1600, y2: 550, ms: 280 } as const;
/** 리스트 중턱에서 손가락 아래 → 목록이 위로. 꼭대기에서 길게 당기면 새로고침이 열린다. */
export const TOWARD_TOP = { y1: 1100, y2: 1700, ms: 280 } as const;
/** 겹침 없이 넘어갔을 때 반쯤 되돌아가는 거리(목록이 아래로). */
export const BACK_HALF = { y1: 1500, y2: 1200, ms: 280 } as const;

function swipeTowardBottom(serial: string) {
	swipeAxis(serial, TOWARD_BOTTOM);
}

function swipeTowardTop(serial: string) {
	swipeAxis(serial, TOWARD_TOP);
}

function swipeAxis(serial: string, axis: { y1: number; y2: number; ms: number }) {
	const x = rand(340, 480);
	adb(serial, [
		"shell",
		"input",
		"swipe",
		String(x),
		String(axis.y1),
		String(x + rand(-20, 20)),
		String(axis.y2),
		String(axis.ms),
	]);
	sleep(300);
}

function scrollUntilStable(serial: string, swipe: (serial: string) => void) {
	let prev = "";
	let stuck = 0;
	for (let i = 0; i < 40; i++) {
		swipe(serial);
		const parsed = parseSalesDump(settledXml(serial));
		if (!parsed.ok) continue;
		const key = visibleKey(parsed.cards);
		if (key && key === prev) {
			stuck += 1;
			if (stuck >= 2) return;
		} else {
			stuck = 0;
		}
		prev = key;
	}
}

function tapSellingTab(serial: string, xml: string) {
	const hit = xml.match(/content-desc="판매중 \d+"[^>]*bounds="\[(\d+),(\d+)\]\[(\d+),(\d+)\]"/);
	if (!hit) return;
	const x = Math.floor((Number(hit[1]) + Number(hit[3])) / 2);
	const y = Math.floor((Number(hit[2]) + Number(hit[4])) / 2);
	adb(serial, ["shell", "input", "tap", String(x), String(y)]);
}

