/** 창을 닫은 뒤 보이던 글과 겹치지 않거나, 걷던 중이 아닌데 맨 위 글이 다시 보이면 목록이 꼭대기로 돌아간 것이다. */
function listJumpedToTop(before: { title: string }[], after: { title: string }[], topTitle: string): boolean {
	if (after.length === 0 || before.length === 0) return false;
	const seen = new Set(before.map((card) => card.title));
	if (!after.some((card) => seen.has(card.title))) return true;
	return topTitle !== "" && after[0]?.title === topTitle && before[0]?.title !== topTitle;
}

function walkUp(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	pending: Map<string, BatchItem>,
	tally: Tally,
	book?: BumpBook,
) {
	const opened = parseSalesDump(dumpXml(serial, exec));
	const topTitle = opened.ok ? (opened.cards[0]?.title ?? "") : "";
	scrollToEdge(serial, exec, ops, "bottom");
	let prev = "";
	let stuck = 0;
	let page = 0;
	for (let turn = 0; turn < 60 && page < 24 && pending.size > 0; turn++) {
		if (stopRequested()) {
			tally.stop = true;
			return;
		}
		let leftList = false;
		const xml = settledXml(serial, exec);
		const nodes = parseNodes(xml);
		const parsed = parseSalesDump(xml);
		if (parsed.ok) {
			// 아래에서 위로 걸을 때는 화면 아래 카드부터. 오래 노출 안 된 글이 먼저다.
			for (const card of [...parsed.cards].reverse()) {
				const item = pending.get(card.title);
				if (!item) continue;
				// 예약중 글은 거래 약속이 잡혀 있다. 저장소가 아직 모르더라도 폰 화면이 예약중이면 건드리지 않는다.
				if (card.reserved) {
					tally.skipped += 1;
					noteSkip(item.title, "당근에서 예약중이라서");
					book?.recordReserved?.(item.id);
					pending.delete(item.title);
					continue;
				}
				if (alreadyAppliedToday(card.price, item.proposedPrice, item.snapshot.price)) {
					tally.skipped += 1;
					tally.already += 1;
					noteSkip(item.title, "카드 가격이 승인된 오늘 가격과 같아서");
					pending.delete(item.title);
					continue;
				}
				const verdict = guardSnapshot(item.snapshot, card);
				if (!verdict.run) {
					tally.skipped += 1;
					noteSkip(item.title, "가격이 승인 때와 달라서");
					pending.delete(item.title);
					continue;
				}
				const visible = item.action === "bump" ? cardBump(nodes, item.title) : moreFor(nodes, item.title);
				if (!visible) continue;
				const done =
					item.action === "bump"
						? bumpOne(serial, exec, ops, item, false, book)
						: priceOne(serial, exec, ops, item, false);
				pending.delete(item.title);
				if (done === "stop") {
					backToSales(serial, exec, ops);
					tally.stop = true;
					return;
				}
				if (done === "bump") tally.bumped += 1;
				else if (done === "price") tally.pricedOnly += 1;
				else tally.skipped += 1;
				if (stopRequested()) {
					tally.stop = true;
					return;
				}
				// 창을 닫으면 목록이 맨 위로 돌아갈 수 있다. 이 덤프의 나머지 카드는 믿지 않는다.
				leftList = true;
				break;
			}
		}
		if (pending.size === 0) break;
		if (leftList) {
			const now = parseSalesDump(settledXml(serial, exec));
			if (now.ok && listJumpedToTop(parsed.ok ? parsed.cards : [], now.cards, topTitle)) {
				scrollToEdge(serial, exec, ops, "bottom");
				prev = "";
				stuck = 0;
				page = 0;
			}
			continue;
		}
		const key = parsed.ok ? parsed.cards.map((card) => card.title).join("|") : "";
		if (page > 0 && key !== "" && key === prev) {
			stuck += 1;
			if (stuck >= 2) break;
		} else {
			stuck = 0;
		}
		prev = key;
		swipeList(serial, exec, ops, "남은 승인 글을 보러", "back");
		page += 1;
	}
	for (const title of pending.keys()) {
		tally.skipped += 1;
		noteSkip(title, "판매중 목록에서 제목을 못 찾음");
	}
}

